def popular_colors_outfit(outfits):

    """
    The function popular_colors_outfit takes a nested list of outfits as a parameter and returns a list with the most popular colors found in the outfits.

    Each outfit is represented by a list of colors, where the colors are represented by strings.

    The function should examine each outfit and count the number of times each color occurs in the outfits. Finally, it should return a list with the colors that occur most frequently, in descending order of occurrence.

    Example:

    popular_colors_outfit([["red", "blue"], ["yellow", "red", "green"], ["blue", "green"]])
    Output: ["red", "blue", "green"]
    """

### Solution:


    color_count = {}

    for outfit in outfits:
        for color in outfit:
            if color in color_count:
                color_count[color] += 1
            else:
                color_count[color] = 1

    sorted_colors = sorted(color_count, key=lambda x: color_count[x], reverse=True)

    return sorted_colors

