### Problem:
def three_most_common(dancers):
    """
    Given a list of dancers, find the three most common elements and return them in descending order.

    Example:
    three_most_common(['Alice', 'Bob', 'Alice', 'John', 'Bob', 'Bob', 'John', 'Eve']) -> ['Bob', 'Alice', 'John']
    """

### Solution:


    dancer_count = {}
    for dancer in dancers:
        if dancer in dancer_count:
            dancer_count[dancer] += 1
        else:
            dancer_count[dancer] = 1
    sorted_dancers = sorted(dancer_count, key=lambda x: dancer_count[x], reverse=True)
    return sorted_dancers[:3]
